package com.tracker.service;
import com.tracker.entity.*; import com.tracker.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class AchievementService {private final StudentAchievementRepository awards;private final SkillRepository skills;private final CourseRepository courses;private final CertificationRepository certs;private final LearningGoalRepository goals;
 public AchievementService(StudentAchievementRepository a,SkillRepository s,CourseRepository c,CertificationRepository x,LearningGoalRepository g){awards=a;skills=s;courses=c;certs=x;goals=g;}
 @Transactional public List<StudentAchievement> reconcile(User u){List<Rule> rules=List.of(new Rule("FIRST_SKILL","First Skill","Record your first skill",10,skills.countByUserId(u.getId())>=1),new Rule("FIRST_COURSE","First Course","Complete your first course",20,courses.findByUserId(u.getId()).stream().anyMatch(c->"COMPLETED".equalsIgnoreCase(c.getStatus()))),new Rule("FIRST_CERTIFICATE","First Certificate","Submit your first certificate",20,certs.countByUserId(u.getId())>=1),new Rule("FIRST_APPROVAL","First Approved Certificate","Receive your first approved certificate",50,certs.countByUserIdAndStatus(u.getId(),CertStatus.APPROVED)>=1),new Rule("FIVE_SKILLS","Five Skills","Record five skills",50,skills.countByUserId(u.getId())>=5),new Rule("GOAL_COMPLETE","Goal Completed","Complete a learning goal",40,goals.countByUserIdAndStatus(u.getId(),"COMPLETED")>=1));for(Rule r:rules)if(r.eligible&&!awards.existsByUserIdAndCode(u.getId(),r.code)){StudentAchievement a=new StudentAchievement();a.setUser(u);a.setCode(r.code);a.setTitle(r.title);a.setDescription(r.description);a.setPoints(r.points);awards.save(a);}return awards.findByUserIdOrderByAwardedAtDesc(u.getId());}
 private record Rule(String code,String title,String description,int points,boolean eligible){}
}
